// Inside an RTK createSlice reducer:

reducers: {
  // ✅ SAFE MUTABLE SYNTAX (Immer handles it)
  addItem: (state, action) => {
    state.items.push(action.payload);
  },

  // ✅ RETURNING NEW STATE (Also perfectly fine!)
  clearItems: (state) => {
    return { ...state, items: [] };
  },

  // ❌ FATAL ERROR (Do not mutate AND return)
  brokenReducer: (state, action) => {
    state.items.push(action.payload);
    return state; // Immer will crash!
  }
}
